{"command":"python3 - <<'PY'
import json,numpy as np
d=json.load(open('initial.json'))
rows=d['observations']
P=np.array([[r['x'],r['y']] for r in rows]);V=np.array([r['value'] for r in rows]);I=np.array([r['impurity'] for r in rows])
S=2*P-1
def des(S,inter):
    x,y=S.T;c=[np.ones(len(x)),x,y,x*x,y*y]
    if inter:c.append(x*y)
    return np.column_stack(c)
for name,Z in [('yield',V),('impurity',I)]:
  for inter in [False,True]:
    A=des(S,inter);coef=np.linalg.lstsq(A,Z,rcond=None)[0];res=Z-A@coef
    print(name,'inter' if inter else 'add',np.round(coef,5),'rmse',round(float(np.sqrt(res@res/max(1,len(Z)-A.shape[1]))),5))
# impurity interaction model evaluate on grid
A=des(S,True);coef=np.linalg.lstsq(A,I,rcond=None)[0]
print('impurity coef interaction',coef)
# unconstrained yield optimum
cy=np.array([95.09959593004072,4.215732579245525,-0.21900106843593825,-6.695041832921262,-5.331163129899495,6.293187321696262])
for x in [0.6,0.65,0.7,0.711,0.75]:
  for y in [0.4,0.45,0.5,0.55,0.61]:
    s=2*np.array([x,y])-1
    v=des(s.reshape(1,2),True)@cy; ii=des(s.reshape(1,2),True)@coef
    print(f'x={x:.3f} y={y:.3f} V={v[0]:.2f} I={ii[0]:.4f}')
PY","description":"Fit yield and impurity surfaces"}

